22	namespace osu.Game.Storyboards.Drawables
23	{
24	    public partial class DrawableStoryboard : Container<DrawableStoryboardLayer>
25	    {
26	        [Cached(typeof(Storyboard))]
27	        public Storyboard Storyboard { get; }
28	
29	        /// <summary>
30	        /// Whether the storyboard is considered finished.
31	        /// </summary>
32	        public IBindable<bool> HasStoryboardEnded => hasStoryboardEnded;
33	
34	        private readonly BindableBool hasStoryboardEnded = new BindableBool(true);
35	
36	        protected override Container<DrawableStoryboardLayer> Content { get; }
37	
38	        protected override Vector2 DrawScale => new Vector2(Parent!.DrawHeight / 480);
39	
40	        public override bool RemoveCompletedTransforms => false;
41	
42	        private double? lastEventEndTime;
43	
44	        [Cached(typeof(IReadOnlyList<Mod>))]
45	        public IReadOnlyList<Mod> Mods { get; }
46	
47	        [Resolved]
48	        private GameHost host { get; set; } = null!;
49	
50	        [Resolved]
51	        private RealmAccess realm { get; set; } = null!;
52	
53	        private DependencyContainer dependencies = null!;
54	
55	        private BindableNumber<double> health = null!;
56	        private readonly BindableBool passing = new BindableBool(true);
57	
58	        protected override IReadOnlyDependencyContainer CreateChildDependencies(IReadOnlyDependencyContainer parent) =>
59	            dependencies = new DependencyContainer(base.CreateChildDependencies(parent));
60	
61	        public DrawableStoryboard(Storyboard storyboard, IReadOnlyList<Mod>? mods = null)
62	        {
63	            Storyboard = storyboard;
64	            Mods = mods ?? Array.Empty<Mod>();
65	
66	            Size = new Vector2(640, 480);
67	
68	            bool onlyHasVideoElements = Storyboard.Layers.SelectMany(l => l.Elements).All(e => e is StoryboardVideo);
69	
70	            Width = Height * (storyboard.Beatmap.WidescreenStoryboard || onlyHasVideoElements ? 16 / 9f : 4 / 3f);
71	
72	            Anchor = Anchor.Centre;
73	            Origin = Anchor.Centre;
74	
75	            AddInternal(Content = new Container<DrawableStoryboardLayer>
76	            {
77	                RelativeSizeAxes = Axes.Both,
78	                Anchor = Anchor.Centre,
79	                Origin = Anchor.Centre,
80	            });
81	        }
82	
83	        [BackgroundDependencyLoader]
84	        private void load(IGameplayClock? clock, CancellationToken? cancellationToken, GameplayState? gameplayState)
85	        {
86	            if (clock != null)
87	                Clock = clock;
88	
89	            dependencies.CacheAs(typeof(TextureStore),
90	                new TextureStore(host.Renderer, host.CreateTextureLoaderStore(
91	                    CreateResourceLookupStore()
92	                ), false, scaleAdjust: 1));
93	
94	            foreach (var layer in Storyboard.Layers)
95	            {
96	                cancellationToken?.ThrowIfCancellationRequested();
97	
98	                Add(layer.CreateDrawable());
99	            }
100	
101	            lastEventEndTime = Storyboard.LatestEventTime;
102	
103	            health = gameplayState?.HealthProcessor.Health.GetBoundCopy() ?? new BindableDouble(1);
104	        }
105	
106	        protected override void LoadComplete()
107	        {
108	            base.LoadComplete();
109	
110	            health.BindValueChanged(val => passing.Value = val.NewValue >= 0.5, true);
111	            passing.BindValueChanged(_ => updateLayerVisibility(), true);
112	        }
113	
114	        protected virtual IResourceStore<byte[]> CreateResourceLookupStore() => new StoryboardResourceLookupStore(Storyboard, realm, host);
115	
116	        protected override void Update()
117	        {
118	            base.Update();
119	            hasStoryboardEnded.Value = lastEventEndTime == null || Time.Current >= lastEventEndTime;
120	        }
121	
122	        public DrawableStoryboardLayer OverlayLayer => Children.Single(layer => layer.Name == "Overlay");
123	
124	        private void updateLayerVisibility()
125	        {
126	            foreach (var layer in Children)
127	                layer.Enabled = passing.Value ? layer.Layer.VisibleWhenPassing : layer.Layer.VisibleWhenFailing;
128	        }
129	
130	        private class StoryboardResourceLookupStore : IResourceStore<byte[]>
131	        {
132	            private readonly IResourceStore<byte[]> realmFileStore;
133	            private readonly Storyboard storyboard;
134	
135	            public StoryboardResourceLookupStore(Storyboard storyboard, RealmAccess realm, GameHost host)
136	            {
137	                realmFileStore = new RealmFileStore(realm, host.Storage).Store;
138	                this.storyboard = storyboard;
139	            }
140	
141	            public void Dispose() =>
142	                realmFileStore.Dispose();
143	
144	            public byte[] Get(string name)
145	            {
146	                string? storagePath = storyboard.GetStoragePathFromStoryboardPath(name);
147	
148	                return string.IsNullOrEmpty(storagePath)
149	                    ? null!
150	                    : realmFileStore.Get(storagePath);
151	            }
152	
153	            public Task<byte[]> GetAsync(string name, CancellationToken cancellationToken = new CancellationToken())
154	            {
155	                string? storagePath = storyboard.GetStoragePathFromStoryboardPath(name);
156	
157	                return string.IsNullOrEmpty(storagePath)
158	                    ? Task.FromResult<byte[]>(null!)
159	                    : realmFileStore.GetAsync(storagePath, cancellationToken);
160	            }
161	
162	            public Stream? GetStream(string name)
163	            {
164	                string? storagePath = storyboard.GetStoragePathFromStoryboardPath(name);
165	
166	                return string.IsNullOrEmpty(storagePath)
167	                    ? null
168	                    : realmFileStore.GetStream(storagePath);
169	            }
170	
171	            public IEnumerable<string> GetAvailableResources() =>
172	                realmFileStore.GetAvailableResources();
173	        }
174	    }
175	}
