21	    /// </summary>
22	    public partial class DimmableStoryboard : UserDimContainer
23	    {
24	        public Container OverlayLayerContainer { get; private set; }
25	
26	        private readonly Storyboard storyboard;
27	        private readonly IReadOnlyList<Mod> mods;
28	
29	        /// <summary>
30	        /// In certain circumstances, the storyboard cannot be hidden entirely even if it is fully dimmed. Such circumstances include:
31	        /// <list type="bullet">
32	        /// <item>
33	        /// cases where the storyboard has an overlay layer sprite, as it should continue to display fully dimmed
34	        /// <i>in front of</i> the playfield (https://github.com/ppy/osu/issues/29867),
35	        /// </item>
36	        /// <item>
37	        /// cases where the storyboard includes samples - as they are played back via drawable samples,
38	        /// they must be present for the playback to occur (https://github.com/ppy/osu/issues/9315).
39	        /// </item>
40	        /// </list>
41	        /// </summary>
42	        private readonly Lazy<bool> storyboardMustAlwaysBePresent;
43	
44	        private DrawableStoryboard drawableStoryboard;
45	
46	        /// <summary>
47	        /// Whether the storyboard is considered finished.
48	        /// </summary>
49	        /// <remarks>
50	        /// This is true by default in here, until an actual drawable storyboard is loaded, in which case it'll bind to it.
51	        /// </remarks>
52	        public IBindable<bool> HasStoryboardEnded = new BindableBool(true);
53	
54	        public DimmableStoryboard(Storyboard storyboard, IReadOnlyList<Mod> mods)
55	        {
56	            this.storyboard = storyboard;
57	            this.mods = mods;
58	
59	            storyboardMustAlwaysBePresent = new Lazy<bool>(() => storyboard.GetLayer(@"Overlay").Elements.Any() || storyboard.Layers.Any(l => l.Elements.OfType<StoryboardSampleInfo>().Any()));
60	        }
61	
62	        [BackgroundDependencyLoader]
63	        private void load()
64	        {
65	            Add(OverlayLayerContainer = new Container());
66	
67	            initializeStoryboard(false);
68	        }
69	
70	        protected override void LoadComplete()
71	        {
72	            ShowStoryboard.BindValueChanged(_ => initializeStoryboard(true), true);
73	            base.LoadComplete();
74	        }
75	
76	        protected override bool ShowDimContent => IgnoreUserSettings.Value || (ShowStoryboard.Value && (DimLevel < 1 || storyboardMustAlwaysBePresent.Value));
77	
78	        private void initializeStoryboard(bool async)
79	        {
80	            if (drawableStoryboard != null)
81	                return;
82	
83	            if (!ShowStoryboard.Value && !IgnoreUserSettings.Value)
84	                return;
85	
86	            drawableStoryboard = storyboard.CreateDrawable(mods);
87	            HasStoryboardEnded.BindTo(drawableStoryboard.HasStoryboardEnded);
88	
89	            if (async)
90	                LoadComponentAsync(drawableStoryboard, onStoryboardCreated);
91	            else
92	                onStoryboardCreated(drawableStoryboard);
93	        }
94	
95	        private void onStoryboardCreated(DrawableStoryboard storyboard)
96	        {
97	            Add(storyboard);
98	            OverlayLayerContainer.Add(storyboard.OverlayLayer.CreateProxy());
99	        }
100	    }
101	}
