13	{
14	    /// <summary>
15	    /// A container that applies user-configured visual settings to its contents.
16	    /// </summary>
17	    public abstract partial class UserDimContainer : Container
18	    {
19	        /// <summary>
20	        /// Amount of lightening to apply to current dim level during break times.
21	        /// </summary>
22	        public const float BREAK_LIGHTEN_AMOUNT = 0.3f;
23	
24	        public const double BACKGROUND_FADE_DURATION = 800;
25	
26	        /// <summary>
27	        /// Whether or not user-configured settings relating to brightness of elements should be ignored.
28	        /// </summary>
29	        /// <remarks>
30	        /// For best or worst, this also bypasses storyboard disable. Not sure this is correct but leaving it as to not break anything.
31	        /// </remarks>
32	        public readonly Bindable<bool> IgnoreUserSettings = new Bindable<bool>();
33	
34	        /// <summary>
35	        /// Whether player is in break time.
36	        /// Must be bound to <see cref="BreakTracker.IsBreakTime"/> to allow for dim adjustments in gameplay.
37	        /// </summary>
38	        public readonly IBindable<bool> IsBreakTime = new Bindable<bool>();
39	
40	        /// <summary>
41	        /// Whether the content of this container is currently being displayed.
42	        /// </summary>
43	        public bool ContentDisplayed { get; private set; }
44	
45	        protected Bindable<double> UserDimLevel { get; private set; } = null!;
46	
47	        /// <summary>
48	        /// The amount of dim to be used when <see cref="IgnoreUserSettings"/> is <c>true</c>.
49	        /// </summary>
50	        public Bindable<float> DimWhenUserSettingsIgnored { get; } = new Bindable<float>();
51	
52	        protected Bindable<bool> LightenDuringBreaks { get; private set; } = null!;
53	
54	        protected Bindable<bool> ShowStoryboard { get; private set; } = null!;
55	
56	        private float breakLightening => LightenDuringBreaks.Value && IsBreakTime.Value ? BREAK_LIGHTEN_AMOUNT : 0;
57	
58	        protected virtual float DimLevel => Math.Max(!IgnoreUserSettings.Value ? (float)UserDimLevel.Value - breakLightening : DimWhenUserSettingsIgnored.Value, 0);
59	
60	        protected override Container<Drawable> Content => dimContent;
61	
62	        private Container dimContent { get; }
63	
64	        /// <summary>
65	        /// Creates a new <see cref="UserDimContainer"/>.
66	        /// </summary>
67	        protected UserDimContainer()
68	        {
69	            AddInternal(dimContent = new Container { RelativeSizeAxes = Axes.Both });
70	        }
71	
72	        [BackgroundDependencyLoader]
73	        private void load(OsuConfigManager config)
74	        {
75	            UserDimLevel = config.GetBindable<double>(OsuSetting.DimLevel);
76	            LightenDuringBreaks = config.GetBindable<bool>(OsuSetting.LightenDuringBreaks);
77	            ShowStoryboard = config.GetBindable<bool>(OsuSetting.ShowStoryboard);
78	
79	            UserDimLevel.ValueChanged += _ => UpdateVisuals();
80	            DimWhenUserSettingsIgnored.ValueChanged += _ => UpdateVisuals();
81	            LightenDuringBreaks.ValueChanged += _ => UpdateVisuals();
82	            IsBreakTime.ValueChanged += _ => UpdateVisuals();
83	            ShowStoryboard.ValueChanged += _ => UpdateVisuals();
84	            IgnoreUserSettings.ValueChanged += _ => UpdateVisuals();
85	        }
86	
87	        protected override void LoadComplete()
88	        {
89	            base.LoadComplete();
90	            UpdateVisuals();
91	        }
92	
93	        /// <summary>
94	        /// Whether the content of this container should currently be visible.
95	        /// </summary>
96	        protected virtual bool ShowDimContent => true;
97	
98	        /// <summary>
99	        /// Should be invoked when any dependent dim level or user setting is changed and bring the visual state up-to-date.
100	        /// </summary>
101	        protected virtual void UpdateVisuals()
102	        {
103	            ContentDisplayed = ShowDimContent;
104	
105	            dimContent.FadeTo(ContentDisplayed ? 1 : 0, BACKGROUND_FADE_DURATION, Easing.OutQuint);
106	            dimContent.FadeColour(OsuColour.Gray(1f - DimLevel), BACKGROUND_FADE_DURATION, Easing.OutQuint);
107	        }
108	    }
